21.T11148/0c055f37730ce8b376e5:
'query=PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?concept ?prefLabel ?altLabel ?definition ?broaderConcept ?broaderLabel
WHERE {
  VALUES ?concept { 
    <21.T11148/b415e16fbe4ca40f2270>
  }

  # Retrieve the preferred label for each concept
  ?concept skos:prefLabel ?prefLabel .
  FILTER(lang(?prefLabel) = "en")

  # Optionally, get alternative labels and definitions
  OPTIONAL { 
    ?concept skos:altLabel ?altLabel .
    FILTER(lang(?altLabel) = "en")
  }
  OPTIONAL { 
    ?concept skos:definition ?definition .
    FILTER(lang(?definition) = "en")
  }

  # Optionally, find any broader concept and its label
  OPTIONAL { 
    ?concept skos:broader ?broaderConcept .
    ?broaderConcept skos:prefLabel ?broaderLabel .
    FILTER(lang(?broaderLabel) = "en")
  }
}
LIMIT 100'
